    [21180]={name="Earthstrike",quality=4,ilvl=66,sourceType="quest_reward",instructions="Reward from the quest 'Champion's Battlegear'. Pick it over the other reward choices.",zone="Silithus",questName="Champion's Battlegear",lore="The badges you collect from performing combat, logistics and tactical assignments for Cenarion Hold are more than just for show. You'd be wise to hold on to them.",proc="Use: Increases your melee and ranged attack power by 280. Â Effect lasts for 20 sec. (2 Min Cooldown)"},
    [21182]={name="Band of Earthen Might",quality=3,ilvl=66,sourceType="quest_reward",instructions="Reward from the quest 'Veteran's Battlegear'. Pick it over the other reward choices.",zone="Silithus",questName="Veteran's Battlegear",lore="The badges you collect from performing combat, logistics and tactical assignments for Cenarion Hold are more than just for show. You'd be wise to hold on to them."},
    [21204]={name="Signet Ring of the Bronze Dragonflight",quality=4,ilvl=75,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'The Path of the Conqueror'.",zone="Tanaris",questName="The Path of the Conqueror"},
    [21242]={name="Blessed Qiraji War Axe",quality=4,ilvl=79,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Imperial Qiraji Armaments'. Pick it over the other reward choices.",zone="Ahn'Qiraj",questName="Imperial Qiraji Armaments",lore="We have not sat idly by for a millennium. We have watched these beasts feast on their own when they have exhausted their utility. We have listened as they have plotted and schemed to destroy our world."},
    [21244]={name="Blessed Qiraji Pugio",quality=4,ilvl=79,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Imperial Qiraji Armaments'. Pick it over the other reward choices.",zone="Ahn'Qiraj",questName="Imperial Qiraji Armaments",lore="We have not sat idly by for a millennium. We have watched these beasts feast on their own when they have exhausted their utility. We have listened as they have plotted and schemed to destroy our world."},
    [21273]={name="Blessed Qiraji Acolyte Staff",quality=4,ilvl=79,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Imperial Qiraji Regalia'. Pick it over the other reward choices.",zone="Ahn'Qiraj",questName="Imperial Qiraji Regalia",lore="I speak of Elementium, mortal. Find and bring me Imperial Qiraji Regalia and the toxic element and I shall infuse weapons of great power."},
    [21278]={name="Stormshroud Gloves",quality=3,ilvl=55,reqLevel=50,sourceType="profession",instructions="Crafted with Leatherworking (requires skill 1).",profession="Leatherworking"},
    [21320]={name="Vest of the Den Watcher",quality=2,ilvl=58,sourceType="quest_reward",instructions="Reward from the quest 'Winterfall Activity'. Pick it over the other reward choices.",zone="Timbermaw Hold",questName="Winterfall Activity",lore="The Timbermaw tend to stay to themselves. While we do allow safe passage to those we trust, we try to avoid other furbolg tribes if at all possible."},
    [21368]={name="Striker's Leggings",quality=4,ilvl=81,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Striker's Leggings'.",zone="Ahn'Qiraj",questName="Striker's Leggings",lore="Bring me a sample of his skin along with other minor components and I shall craft you leggings of great power."},
    [21370]={name="Striker's Hauberk",quality=4,ilvl=88,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Striker's Hauberk'.",zone="Ahn'Qiraj",questName="Striker's Hauberk",lore="The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj. The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power."},
    [21403]={name="Cloak of the Unseen Path",quality=4,ilvl=67,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Cloak of the Unseen Path'.",zone="Ahn'Qiraj",questName="Cloak of the Unseen Path",lore="I'm glad to hear you're aiding us in our attack on Ahn'Qiraj. I can make you a protective item that'll be of assistance in the fight against our enemy."},
    [21477]={name="Ring of Fury",quality=3,ilvl=74,reqLevel=60,sourceType="boss_drop",instructions="Drops from Moam.",zone="Ruins of Ahn'Qiraj",npc="Moam",lore="A stone giant pressed into qiraji service, who drains the mana of everyone fighting him and turns to rock when full."},
    [21567]={name="Rune of Duty",quality=3,ilvl=45,reqLevel=40,sourceType="vendor",instructions="Bought from the Warsong Gulch quartermaster with marks of honor. Alliance: Illiyana Moonblaze at Silverwing Grove, Ashenvale. Horde: Kelm Hargunth at Mor'shan Base Camp, The Barrens."},
    [21568]={name="Rune of Duty",quality=3,ilvl=25,reqLevel=20,sourceType="vendor",instructions="Bought from the Warsong Gulch quartermaster with marks of honor. Alliance: Illiyana Moonblaze at Silverwing Grove, Ashenvale. Horde: Kelm Hargunth at Mor'shan Base Camp, The Barrens."},
    [21586]={name="Belt of Never-ending Agony",quality=4,ilvl=88,reqLevel=60,sourceType="boss_drop",instructions="Drops from C'Thun.",zone="Temple of Ahn'Qiraj",npc="C'Thun",lore="An Old God, buried under Ahn'Qiraj by the titans rather than killed. It has been whispering to the qiraji ever since, and the whole war exists because it never stopped."},
    [21602]={name="Qiraji Execution Bracers",quality=4,ilvl=81,reqLevel=60,sourceType="boss_drop",instructions="Drops from Emperor Vek'lor.",zone="Temple of Ahn'Qiraj",npc="Emperor Vek'lor",lore="Twin emperor of the qiraji, and the one who inherited C'Thun's gift for magic instead of his brother's strength. Neither twin can be killed far from the other."},
    [21664]={name="Barbed Choker",quality=4,ilvl=77,reqLevel=60,sourceType="boss_drop",instructions="Drops from Fankriss the Unyielding.",zone="Temple of Ahn'Qiraj",npc="Fankriss the Unyielding",lore="A vast qiraji burrower that spawns its young mid-fight and hurls intruders into the walls."},
    [21672]={name="Gloves of Enforcement",quality=4,ilvl=76,reqLevel=60,sourceType="boss_drop",instructions="Drops from Battleguard Sartura.",zone="Temple of Ahn'Qiraj",npc="Battleguard Sartura",lore="The qiraji empire's finest soldier, who fights with her honour guard and refuses to be separated from them."},
    [21710]={name="Cloak of the Fallen God",quality=4,ilvl=88,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'The Savior of Kalimdor'. Pick it over the other reward choices.",zone="Ahn'Qiraj",questName="The Savior of Kalimdor",lore="To the Caverns of Time you go, Lord:Lady;. Anachronos awaits your return. Give him the eye of C'Thun as he will undoubtedly wish to place it in his master's collection."},
    [21809]={name="Fury of the Forgotten Swarm",quality=3,ilvl=71,reqLevel=60,sourceType="boss_drop",instructions="Drops from Colonel Zerran.",zone="Ruins of Ahn'Qiraj",npc="Colonel Zerran"},
    [22060]={name="Beastmaster's Tunic",quality=4,ilvl=60,sourceType="quest_reward",instructions="Reward from the quest 'Saving the Best for Last'.",zone="Ironforge",questName="Saving the Best for Last",lore="That's an amazing story! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut."},
    [22061]={name="Beastmaster's Boots",quality=4,ilvl=60,sourceType="quest_reward",instructions="Reward from the quest 'Anthion's Parting Words'.",zone="Ironforge",questName="Anthion's Parting Words",lore="Valthalak's soul was stored in this amulet. In our greed we foolishly split it into three parts, not knowing the curse that would await us. The only way to stop Valthalak's spell is to put the medallion back together."},
    [22150]={name="Beads of Ogre Might",quality=3,ilvl=63,sourceType="quest_reward",instructions="Reward from the quest 'Falrin's Vendetta'. Pick it over the other reward choices.",zone="Dire Maul",questName="Falrin's Vendetta",lore="Yet I'm not one to give out favors freely, even if you were sent here by an old friend. I hold nothing but hatred and contempt for our brutish ogre neighbors."},
